<section class="content-area" aria-labelledby="page-title"><div class="container-fluid"><h1 id="page-title" class="h3 mb-2">Assistant Settings</h1><p class="text-muted mb-4">Prototype settings are held in this browser only.</p><div class="card"><div class="card-body"><form id="settingsForm" class="row g-3 needs-validation" novalidate><div class="col-md-6"><label class="form-label" for="assistantName">Assistant name</label><input class="form-control" id="assistantName" value="Saha+ Health Assistant" required></div><div class="col-md-6"><label class="form-label" for="emergencyNumber">Emergency number</label><input class="form-control" id="emergencyNumber" value="190" inputmode="numeric" required></div><div class="col-12"><label class="form-label" for="welcomeMessage">Welcome message</label><textarea class="form-control" id="welcomeMessage" rows="2" required>Hello, I’m Saha+. Ask me for general health information or prevention tips.</textarea></div><div class="col-12"><label class="form-label" for="disclaimerText">Disclaimer text</label><input class="form-control" id="disclaimerText" value="Saha+ is educational. It does not diagnose or prescribe." required></div><div class="col-md-6"><label class="form-label" for="assistantLanguage">Language</label><select class="form-select" id="assistantLanguage"><option>English</option><option>Français</option><option>العربية</option></select></div><div class="col-md-6 d-flex align-items-end"><div class="form-check form-switch mb-2"><input class="form-check-input" type="checkbox" role="switch" id="widgetEnabled" checked><label class="form-check-label" for="widgetEnabled">Show floating assistant widget</label></div></div><div class="col-12"><button class="btn btn-primary" type="submit">Save settings</button><span class="small ms-3" id="settingsStatus" role="status"></span></div></form></div></div></div></section>
